const bar=(v,m,c,w)=>`<span style="display:inline-block;width:${w||110}px;height:9px;background:#333;border-radius:5px;vertical-align:middle"><i style="display:block;height:9px;width:${Math.max(0,Math.min(100,100*v/m))}%;background:${c};border-radius:5px"></i></span>`;
