function enchHTML(g,sl){ if(g.ench) return '<br>✨ '+enchTxt(g.ench); const S=GR.enchSlots(g.q); if(!S.a) return ''; const ri=st.c.realmIdx||0, amt=GR.enchAttrAmt(ri), so=(id)=>`<select id=${id}>${GR.ENCH_ATTR.map(a=>`<option>${a}</option>`).join('')}</select>`, sc=(id)=>`<select id=${id}>${Object.keys(GR.ENCH_COMBAT).map(k=>`<option value=${k}>${GR.ENCH_CN[k]} +${Math.round(GR.ENCH_COMBAT[k]*100)}%</option>`).join('')}</select>`;
 return `<div class=tip style="margin-top:6px"><b>✨ Enchant (permanent, your pick)</b><br>Attribute +${amt}: ${so('ea1')}${S.a>1?so('ea2'):''}<br>Combat: ${sc('ec1')}${S.c>1?sc('ec2'):''}${S.u?`<br>Unique: <b>${GR.UNIQ[sl][1]}</b>`:''}<br><button class=dbuy onclick="Demo.enchant('${sl}')">Enchant permanently</button></div>`; }
function enchant(sl){ const d=D(), g=d.eq[sl]; if(!g||g.ench) return; const S=GR.enchSlots(g.q); if(!S.a) return; const amt=GR.enchAttrAmt(st.c.realmIdx||0), e={attr:{},combat:{}}; ['ea1','ea2'].slice(0,S.a).forEach(id=>{ const v=$('#'+id).value; e.attr[v]=(e.attr[v]||0)+amt; }); ['ec1','ec2'].slice(0,S.c).forEach(id=>{ const v=$('#'+id).value; e.combat[v]=+((e.combat[v]||0)+GR.ENCH_COMBAT[v]).toFixed(3); }); if(S.u) e.u=GR.UNIQ[sl][0]; g.ench=e; d.ct.ench=1; feat(d,'You','✨','enchanted '+g.n); SYS.checkAch(st); toast('Enchanted '+g.n+' ✓'); re('Enchanted '+g.n+': '+enchTxt(e)+'.'); }
function tome(i){ const d=D(), q=st.qi, ri=st.c.realmIdx||0, [n,ic,pr]=SYS.TOMES[i], p=pr[Math.min(3,ri)]; d.tomes=d.tomes||{}; d.tomes[ri]=d.tomes[ri]||{}; if(d.tomes[ri][n]) return re(n+' already read this realm.'); if(q.gold<p) return re('Need '+p+' gold.'); q.gold-=p; d.tomes[ri][n]=1;
 const known=Object.keys(q.techs), hid=GR.RECIPES.filter(r=>(r.path===P()||(ri>=2&&r.path==='Body'))&&!known.includes(r.n)&&ri>=GR.TIER_RI[r.tier]&&!d.hints.some(h=>h.startsWith(r.n))), val=combos().filter(r=>!d.hints.some(h=>h.startsWith(r.n))); let m='';
 if(i===0){ const r=val[0]; m=r?`Every pattern includes Meditation. Your easiest open pattern: ${r.n} (${r.in.filter(x=>x!=='Meditation').join(' + ')}).`:'Every pattern includes Meditation. You have no open pattern right now; buy a manual.'; if(r) d.hints.push(`${r.n} (${r.tier}): meditate on ${r.in.filter(x=>x!=='Meditation').join(' + ')}.`); }
 else if(i===1){ const r=hid.find(r=>!val.includes(r))||hid[0]; m=r?`A hidden ${r.tier} pattern of ${r.T.fx==='heal'||r.T.fx==='regen'?'mending':r.T.fx==='shield'||r.T.fx==='dr'?'protection':r.T.fx?'focus':'attack'} exists for you; one of its inputs is ${r.in.filter(x=>x!=='Meditation')[0]}.`:'The Treatise finds nothing hidden from you in this realm.'; }
 else { const r=hid[0]; m=r?`${r.n} (${r.tier}): meditate on ${r.in.filter(x=>x!=='Meditation').join(' + ')}.`:'The Codex has nothing new for you.'; if(r) d.hints.push(m); }
 d.news.push(ic+' '+n+': '+m); SYS.checkAch(st); toast('Read the '+n+' ✓'); re(ic+' '+n+': '+m); }
function suggestForm(){ view(`<div class=dh><h2>💡 Suggest an idea</h2>Anything about DBG: a technique, combo, physique or game improvement. Suggestions go to the weekly review; adopted ideas apply at the Monday update and are credited in the changelog.</div><select id=sugTag>${SYS.TAGS.map(t=>`<option>${t}</option>`).join('')}</select><textarea id=sugTxt maxlength=600 style="width:100%;min-height:120px" placeholder="Your idea"></textarea><button class=dgo onclick="Demo.sendSuggest()">Send for weekly review</button><button class=s onclick="Demo.tab('hub')">Cancel</button>`); chrome(); }
function p28sheet(){ if(!root.SYS) return ''; SYS.ensure(st); const d=D(), c=st.c, X=SYS.derived(st), A=SYS.attrs(st), P=d.phys, pc=x=>Math.round(x*100)+'%';
 const maj=Object.keys(P.maj).map(k=>[k,SYS.MAJOR[k].t[P.maj[k]][0]]), mins=P.min.map(k=>[k,SYS.MINOR[k].n]);
 return `<div class=cmp><b>Cultivation readout</b> <small>(soft caps: Spd/Tough/Aff 51–100 at 90%, 101–150 at 80%, 151+ at 70%)</small><br>Effective: Str ${A.eff.Str} · Spd ${Math.round(A.eff.Spd)} · Tough ${Math.round(A.eff.Tough)} · Aff ${Math.round(A.eff.Aff)}<br>HP ${X.hp.toLocaleString()} · Mana ${X.mana.toLocaleString()} · Physical ${X.phys.toLocaleString()} · Affinity ${X.aff.toLocaleString()} · Hybrid ${X.hybrid.toLocaleString()}<br>Crit ${pc(X.crit)} (×1.5) · Dodge ${pc(X.dodge)} (cap 50%) · Block ${pc(X.block)} · Gear DR ${pc(X.dr)} (total cap 60%)<br><small style="color:#9ab">Battles apply these relative to a default build of your role and realm, so the tuned fights stay fair.</small></div>
 <div class=cmp><b>🧬 Physiques</b> <small>(1 Major + 1 Minor active)</small><br>Major: <select onchange="Demo.setMajor(this.value)"><option value="">—</option>${maj.map(([k,n])=>`<option value=${k} ${P.aM===k?'selected':''}>${n}</option>`).join('')}</select> Minor: <select onchange="Demo.setMinor(this.value)"><option value="">—</option>${mins.map(([k,n])=>`<option value=${k} ${P.am===k?'selected':''}>${n}</option>`).join('')}</select><br><small>${P.aM?SYS.MAJOR[P.aM].fx:'Majors are discovered in Meditation from Foundation (Strength line: Tempered Sinew at Qi level 5 if Strength is your top attribute).'}${P.am?' · '+SYS.MINOR[P.am].fx:''}</small><br><small style="color:#9ab">Minor milestones: ${Object.keys(SYS.MINOR).filter(k=>!P.min.includes(k)).slice(0,4).map(k=>SYS.MINOR[k].n+' — '+SYS.MINOR[k].how).join(' · ')}${Object.keys(SYS.MINOR).length-P.min.length>4?' …':''}</small></div>
 <div class=cmp><b>Title</b> <select onchange="Demo.setTitle(this.value)">${d.titles.map(t=>`<option ${d.title===t?'selected':''}>${SYS.esc(t)}</option>`).join('')}</select> · 🏅 ${SYS.achPts(d)}/${SYS.ACH_PTS} achievement points (${Object.keys(d.ach).length}/30) · ✨ ${d.insp}/3 · 🏮 ${d.charges}/3
 <div style="font-size:11px;color:#9ab;max-height:90px;overflow:auto">${SYS.ACH.map(([k,n,p,how])=>`${d.ach[k]?'✅':'▫️'} ${n} (${p}) — ${how}`).join('<br>')}</div></div>
 <label>Character bio (optional)<textarea maxlength=1500 oninput="Demo.bio(this.value)">${SYS.esc(c.bio||'')}</textarea></label>`; }
function sharedResult(o){ const d=D(); if(!root.SYS) return; SYS.ensure(st); d.resDone=d.resDone||{}; if(d.resDone[o.id]) return; d.resDone[o.id]=1; const C=SYS.contribution(o.g,o.seat,o.adv);
 d.ct.joins++; d.ct.fights++; if(o.win){ d.wc+=C.pts; d.ct.bossWins++; if(C.mvp) d.ct.mvps++; } const u=C.u; if(u){ d.ct.crits+=u.crits||0; d.ct.firsts+=u.firsts||0; d.ct.debuffs+=u.debs||0; d.ct.potions+=u.pots||0; }
 if(o.win&&u){ if(C.top.dmg){ d.ct.topDmg++; if(!d.titles.includes('Worldbreaker')) d.titles.push('Worldbreaker'); } const most=o.g.units.slice().sort((a,b)=>(b.taken||0)-(a.taken||0))[0]; if(most===u&&!u.down){ d.ct.tanked++; } if(C.top.pro&&!d.titles.includes('The Unyielding')) d.titles.push('The Unyielding'); if(C.top.sus&&!d.titles.includes('Beacon of Heaven')) d.titles.push('Beacon of Heaven'); if(C.top.con&&!d.titles.includes('Master of Fate')) d.titles.push('Master of Fate'); if(C.mvp&&!d.titles.includes('Party Favorite')) d.titles.push('Party Favorite');
  if(!o.g.units.some(x=>x.down)) d.ct.unbroken=1; if(!u.down&&u.hp/u.mx<.1) d.ct.last=1;
  if(o.adv){ const roll=1+Math.floor(Math.random()*20); if(roll>=10) SYS.addInsp(st,1,'advancement victory, d20 '+roll); if(C.mvp) SYS.addInsp(st,1,'advancement MVP'); }
  if(o.chal){ d.ct.chal[o.chal]=(d.ct.chal[o.chal]||0)+1; d.ct.chalWins++; d.chalWeek=d.chalWeek&&d.chalWeek.w===o.week?d.chalWeek:{w:o.week,n:{}}; d.chalWeek.n[o.chal]=(d.chalWeek.n[o.chal]||0)+1; }
  if(o.ruin){ const ch=['dmg','pro','sus','con'], tot={}; ch.forEach(k=>tot[k]=o.g.units.reduce((a,x)=>a+(x.sc[k]||0),0)||1); const best=ch.map(k=>[k,(u.sc[k]||0)/tot[k]]).sort((a,b)=>b[1]-a[1])[0][0]; d.relic={dmg:'Fang of the Broken World',pro:'Unfallen Bulwark',sus:'Lantern of the Long Night',con:'Chain of Fate'}[best]; } }
 d.news.push(`Weekend contribution: +${o.win?C.pts:0} (${C.mvp?'MVP · ':''}${o.adv?'advancement ×2':'challenge'}).`); SYS.checkMinors(st).forEach(n=>d.news.push('🧬 Minor physique: '+n+'!')); SYS.checkAch(st); save(); }
