 const out={game:'DBG',version:'p28',exported:new Date().toISOString(),name:c.name,role:c.role,bio:c.bio||'',realm:c.realm,level:c.level,ranking:rows.findIndex(r=>r===me)+1,score:me.total,categories:me.cat,title:d.title,endTitle:me.endTitle,titles:d.titles,achievements:Object.keys(d.ach),discoveries:Object.keys(q.techs).filter(t=>FF.TECH[t]&&FF.TECH[t].promo),physiques:{major:Object.keys(d.phys.maj).map(k=>SYS.MAJOR[k].t[d.phys.maj[k]][0]),minor:d.phys.min.map(k=>SYS.MINOR[k].n)},legendaryEquipment:Object.values(d.eq||{}).concat(q.inv).filter(g=>g&&g.q==='Legendary').map(g=>g.n),campaign:{bossWins:d.ct.bossWins,challengeWins:d.ct.chalWins,elites:d.ct.elites,rares:d.ct.rares,weekendContribution:d.wc,ruinDefeated:!!d.ruin},relics:[d.relic,me===rows[0]?'Crown of This Age':null].filter(Boolean)};
